#include <iostream>
#include <algorithm>
#include <climits>
using namespace std;

int main() {
    unsigned long long n;
    cin >> n;

    int dp[2] = {0, INT_MIN / 2};

    do {
        int digit = n % 10;
        n /= 10;

        int next[2] = {INT_MIN / 2, INT_MIN / 2};

        for (int carry = 0; carry <= 1; ++carry) {
            for (int a = 0; a <= 9; ++a) {
                for (int b = 0; b <= 9; ++b) {
                    int sum = a + b + carry;
                    if (sum % 10 == digit) {
                        next[sum / 10] = max(next[sum / 10],
                                             dp[carry] + a + b);
                    }
                }
            }
        }

        dp[0] = next[0];
        dp[1] = next[1];
    } while (n > 0);

    cout << dp[0];
    return 0;
}

#include <iostream>
#include <algorithm>

using LL = long long;

LL digitSum(LL x) {
    LL sum = 0;
    while (x > 0) {
        sum += x % 10;
        x /= 10;
    }
    return sum;
}

int main() {
    LL n;
    std::cin >> n;

    LL ans = digitSum(n);

    for (__int128 p = 10; p <= static_cast<__int128>(n) + 1; p *= 10) {
        for (int k = 1; k <= 9; ++k) {
            __int128 value = k * p - 1;
            if (value <= n) {
                LL a = static_cast<LL>(value);
                ans = std::max(ans, digitSum(a) + digitSum(n - a));
            }
        }
    }

    std::cout << ans;
    return 0;
}

#include <iostream>
#include <algorithm>

using LL = long long;

LL cnt(LL x) {
    LL sum = 0;
    while (x > 0) {
        sum += x % 10;
        x /= 10;
    }
    return sum;
}

int main() {
    LL n;
    std::cin >> n;

    LL ans = cnt(n);

    for (__int128 base = 10; base - 1 <= n; base *= 10) {
        for (int k = 1; k <= 9; ++k) {
            __int128 value = k * base - 1;
            if (value > n) break;

            LL x = static_cast<LL>(value);
            ans = std::max(ans, cnt(x) + cnt(n - x));
        }
    }

    std::cout << ans;
    return 0;
}

#include <iostream>
#include <algorithm>

using LL = long long;

LL digitSum(LL x) {
    LL sum = 0;
    while (x > 0) {
        sum += x % 10;
        x /= 10;
    }
    return sum;
}

int main() {
    LL n;
    std::cin >> n;

    LL ans = digitSum(n);
    __int128 power = 10;
    __int128 suffix = 9;

    while (suffix <= n) {
        for (int digit = 0; digit <= 8; ++digit) {
            __int128 candidate = digit * power + suffix;
            if (candidate > n) break;

            LL a = static_cast<LL>(candidate);
            ans = std::max(ans, digitSum(a) + digitSum(n - a));
        }

        suffix += 9 * power;
        power *= 10;
    }

    std::cout << ans;
    return 0;
}

#include <iostream>
#include <algorithm>

int main() {
    long long n;
    std::cin >> n;

    int dp[2] = {0, -1000000};

    do {
        const int digit = static_cast<int>(n % 10);
        int next[2] = {-1000000, -1000000};

        for (int carry = 0; carry <= 1; ++carry) {
            if (dp[carry] < 0) continue;

            for (int a = 0; a <= 9; ++a) {
                for (int b = 0; b <= 9; ++b) {
                    const int sum = a + b + carry;
                    if (sum % 10 == digit) {
                        next[sum / 10] =
                            std::max(next[sum / 10], dp[carry] + a + b);
                    }
                }
            }
        }

        dp[0] = next[0];
        dp[1] = next[1];
        n /= 10;
    } while (n > 0);

    std::cout << dp[0];
    return 0;
}

